    if (stats.isDirectory()) {
      collect(abs, rel, out);
    } else if (stats.isFile()) {
      if (rel === MANIFEST) continue;
      out.push(rel);
    }
  }
}

const files = [];
collect(ROOT, '', files);
files.sort();

fs.writeFileSync(path.join(ROOT, MANIFEST), `${JSON.stringify({ files }, null, 2)}\n`);
console.log(...);
