const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const MANIFEST_NAME = 'backup-manifest.json';
const MANIFEST_PATH = path.join(ROOT, MANIFEST_NAME);

function isHidden(name) {
  return name.startsWith('.');
}

function collect(dir, relBase, files) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const name = entry.name;
    if (isHidden(name)) continue;

    const abs = path.join(dir, name);
    const rel = relBase ? `${relBase}/${name}` : name;

    let stats;
    try {
      stats = fs.lstatSync(abs);
    } catch {
      continue;
    }

    if (stats.isSymbolicLink()) {
      let target;
      try {
        target = fs.statSync(abs);
      } catch {
        continue;
      }
      if (target.isFile()) files.push(rel);
      continue;
    }

    if (stats.isDirectory()) {
      collect(abs, rel, files);
    } else if (stats.isFile()) {
      if (abs === MANIFEST_PATH) continue;
      files.push(rel);
    }
  }
}

const files = [];
collect(ROOT, '', files);
files.sort();

fs.writeFileSync(MANIFEST_PATH, `${JSON.stringify({ files }, null, 2)}\n`);

console.log(`Wrote ${MANIFEST_NAME} with ${files.length} file(s):`);
for (const file of files) console.log(`  ${file}`);

